"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import { useColorInput, type UseColorInputOptions } from "./use-color-input"

export interface ColorInputProps extends UseColorInputOptions {
  label?: ReactNode
  hint?: ReactNode
  /** Show the native OS picker alongside the text field. Default true. */
  nativePicker?: boolean
  /** Show the swatch palette. Default true. */
  showSwatches?: boolean
  /** Show the live contrast reading when `contrastAgainst` is set. Default true. */
  showContrast?: boolean
}

/**
 * A colour field.
 *
 * Emits canonical uppercase hex by default, so two equal colours are always
 * string-equal. `contrastAgainst` + `minContrast` turn an accessibility bug
 * into a warning at the point the colour is chosen.
 */
export const ColorInput = forwardRef<HTMLInputElement, ColorInputProps>(
  function ColorInput(
    {
      label,
      hint,
      nativePicker = true,
      showSwatches = true,
      showContrast = true,
      className,
      id: idProp,
      ...rest
    },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useColorInput({ ...rest, id })
    const {
      inputProps,
      nativeProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      hex,
      swatches,
      selectSwatch,
      contrast,
    } = api

    useImperativeHandle(
      ref,
      () =>
        inputProps.ref.current ??
        ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement),
      [inputProps.ref],
    )

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        <div
          className="inputcn-group"
          data-invalid={ariaProps["aria-invalid"] ? "true" : undefined}
        >
          <span className="inputcn-affix" aria-hidden="true">
            <span
              className="inputcn-colorwell"
              style={hex ? { background: hex } : undefined}
              data-empty={hex ? undefined : "true"}
            />
          </span>
          <input
            {...inputProps}
            {...ariaProps}
            id={id}
            className="inputcn-bare inputcn-mono"
            aria-label={rest["aria-label"]}
            aria-labelledby={rest["aria-labelledby"]}
          />
          {nativePicker ? (
            <span className="inputcn-affix inputcn-affix-right">
              <input {...nativeProps} className="inputcn-native-color" />
            </span>
          ) : null}
        </div>

        {showSwatches && swatches.length > 0 ? (
          <div className="inputcn-swatches" role="group" aria-label="Colour presets">
            {swatches.map((s) => (
              <button
                key={s}
                type="button"
                className="inputcn-swatch"
                style={{ background: s }}
                aria-label={s}
                aria-pressed={s.toUpperCase() === hex.toUpperCase()}
                disabled={rest.disabled}
                onClick={() => selectSwatch(s)}
              />
            ))}
          </div>
        ) : null}

        {showContrast && contrast ? (
          <p className="inputcn-contrast" data-level={contrast.level}>
            <span className="inputcn-contrast-ratio">{contrast.ratio}:1</span>
            <span>
              {contrast.level === "fail" ? "below AA" : contrast.level} against{" "}
              {contrast.against}
            </span>
          </p>
        ) : null}

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import { custom, required as requiredRule, rules } from "@inputcn/core/validity"

import {
  DEFAULT_SWATCHES,
  bestForeground,
  contrastRatio,
  format,
  parseColor,
  parsePastedColor,
  toHex,
  wcagLevel,
  type ColorFormat,
  type RGB,
  type WcagLevel,
} from "./color"

export interface ColorConstraints {
  /**
   * Check contrast against this colour. The differentiating constraint: it
   * stops a customer picking a brand colour nobody can read.
   */
  contrastAgainst?: string
  /** Minimum WCAG ratio. 4.5 is AA for body text, 3 is AA for large text. */
  minContrast?: number
  /** Restrict to a palette. */
  allowed?: readonly string[]
}

export interface UseColorInputOptions
  extends BaseFieldProps<string>,
    ColorConstraints {
  /** Output format for `onChange`. Default "hex" — the only lossless one. */
  outputFormat?: ColorFormat
  /** Palette shown beneath the field. */
  swatches?: readonly string[]
}

export interface UseColorInputResult extends UseFieldResult<string> {
  /** Parsed value, or null while the text is incomplete. */
  rgb: RGB | null
  /** Canonical hex for the preview swatch, or "" when unparseable. */
  hex: string
  /** Readable text colour on top of the current value. */
  readableOn: "#000000" | "#FFFFFF"
  contrast: { ratio: number; level: WcagLevel; against: string } | null
  swatches: readonly string[]
  selectSwatch: (value: string) => void
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    onBlur: () => void
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    spellCheck: false
    autoComplete: "off"
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
  nativeProps: {
    type: "color"
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    disabled: boolean | undefined
    tabIndex: -1
    "aria-label": string
  }
}

const EMPTY = ""
const BLACK: RGB = { r: 0, g: 0, b: 0, a: 1 }

/**
 * Contrast is a WARNING, not an error: a brand colour that fails AA is a
 * decision to reconsider, not an input to refuse. The measured ratio is
 * captured on the failing call so the message can quote it.
 */
function makeContrastRule(
  against: RGB,
  minContrast: number,
  againstLabel: string,
): Rule<string> {
  let measured = 0
  return {
    rule: "colorContrast",
    warning: true,
    get params() {
      return {
        against: againstLabel,
        minContrast,
        ratio: Math.round(measured * 100) / 100,
      }
    },
    test: (v: string) => {
      const c = parseColor(v)
      if (c === null) return true
      measured = contrastRatio(c, against)
      return measured >= minContrast
    },
  } as Rule<string>
}

export function useColorInput(options: UseColorInputOptions): UseColorInputResult {
  const {
    contrastAgainst,
    minContrast,
    allowed,
    outputFormat = "hex",
    swatches = DEFAULT_SWATCHES,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const against = useMemo(
    () => (contrastAgainst ? parseColor(contrastAgainst) : null),
    [contrastAgainst],
  )

  const allowedSet = useMemo(
    () => (allowed ? new Set(allowed.map((c) => toHex(parseColor(c) ?? BLACK))) : null),
    [allowed],
  )

  const ruleList = useMemo<ReadonlyArray<Rule<string>>>(
    () =>
      rules<string>(
        requiredRule<string>(required),
        { rule: "colorFormat", test: (v) => parseColor(v) !== null },
        allowedSet && {
          rule: "oneOf",
          params: { allowed },
          test: (v) => {
            const c = parseColor(v)
            return c === null || allowedSet.has(toHex(c))
          },
        },
        against && minContrast !== undefined && makeContrastRule(against, minContrast, contrastAgainst!),
        custom<string>(validate),
      ),
    [required, allowedSet, allowed, against, minContrast, contrastAgainst, validate],
  )

  const field = useField<string>({
    component: "ColorInput",
    emptyValue: EMPTY,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
  })

  const { value, setValue } = field
  const ref = useRef<HTMLInputElement | null>(null)

  const rgb = useMemo(() => parseColor(value), [value])
  const hex = rgb ? toHex(rgb) : ""
  const readableOn = rgb ? bestForeground(rgb) : "#000000"

  const contrast = useMemo(() => {
    if (!rgb || !against || !contrastAgainst) return null
    const ratio = contrastRatio(rgb, against)
    return { ratio: Math.round(ratio * 100) / 100, level: wcagLevel(ratio), against: contrastAgainst }
  }, [rgb, against, contrastAgainst])

  /**
   * Draft holds partial text. Without it, typing "#3" would be unparseable,
   * emit nothing, and the field would fight the user on every keystroke.
   */
  const [draft, setDraft] = useState<string | null>(null)
  const display = draft ?? value

  const emit = useCallback(
    (c: RGB) => setValue(format(c, outputFormat)),
    [setValue, outputFormat],
  )

  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = e.currentTarget.value
      setDraft(text)
      const parsed = parseColor(text)
      // Emit the canonical form when it parses, and the raw text when it does
      // not. Emitting "" for unparseable input would leave the value empty,
      // which skips every non-required rule and silently shows no error.
      setValue(parsed ? format(parsed, outputFormat) : text)
    },
    [disabled, readOnly, setValue, outputFormat],
  )

  // Normalising on blur is what turns "3a3fd6" into "#3A3FD6".
  const onBlur = useCallback(() => setDraft(null), [])

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      const parsed = parsePastedColor(text)
      if (!parsed) return
      setDraft(null)
      emit(parsed)
    },
    [disabled, readOnly, emit],
  )

  const selectSwatch = useCallback(
    (swatch: string) => {
      if (disabled || readOnly) return
      const parsed = parseColor(swatch)
      if (!parsed) return
      setDraft(null)
      emit(parsed)
    },
    [disabled, readOnly, emit],
  )

  const onNativeChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const parsed = parseColor(e.currentTarget.value)
      if (!parsed) return
      setDraft(null)
      emit(parsed)
    },
    [emit],
  )

  const inputProps = useMemo(
    () => ({
      ref,
      value: display,
      onChange,
      onBlur,
      onPaste,
      spellCheck: false as const,
      autoComplete: "off" as const,
      disabled,
      readOnly,
      placeholder: placeholder ?? "#000000",
    }),
    [display, onChange, onBlur, onPaste, disabled, readOnly, placeholder],
  )

  const nativeProps = useMemo(
    () => ({
      type: "color" as const,
      // <input type=color> only accepts 6-digit hex; alpha would break it.
      value: hex.slice(0, 7) || "#000000",
      onChange: onNativeChange,
      disabled,
      tabIndex: -1 as const,
      // The text field is the accessible control; this is a mouse convenience,
      // so it is removed from the tab order and labelled for anyone who lands
      // on it anyway.
      "aria-label": "Pick a colour visually",
    }),
    [hex, onNativeChange, disabled],
  )

  return {
    ...field,
    rgb,
    hex,
    readableOn,
    contrast,
    swatches,
    selectSwatch,
    inputProps,
    nativeProps,
  }
}

/**
 * Colour parsing, conversion and contrast. Framework-free.
 *
 * Canonical value is a hex string: `"#3A3FD6"`. Uppercase, always 6 digits
 * (alpha is carried separately when present), so two equal colours are always
 * string-equal — which matters the moment you diff or dedupe them.
 *
 * The contrast maths is the point of this module. `contrastAgainst` +
 * `minContrast` stops a customer picking a brand colour nobody can read, which
 * is an accessibility bug caught at the source rather than in an audit.
 */

import { scrub } from "@inputcn/core/paste"

export type ColorFormat = "hex" | "rgb" | "hsl"

export interface RGB {
  r: number
  g: number
  b: number
  /** 0–1. */
  a: number
}

// Hoisted — these run on every keystroke.
const HEX_RE = /^#?([a-f\d]{3,8})$/i
const RGB_RE = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.%]+))?\s*\)$/i
const HSL_RE = /^hsla?\(\s*([\d.]+)(?:deg)?[\s,]+([\d.]+)%[\s,]+([\d.]+)%(?:[\s,/]+([\d.%]+))?\s*\)$/i

const clamp = (n: number, lo: number, hi: number) => (n < lo ? lo : n > hi ? hi : n)
const byte = (n: number) => clamp(Math.round(n), 0, 255)

/** Parse hex, rgb() or hsl(). Returns null when unrecognisable. */
export function parseColor(input: string): RGB | null {
  const text = scrub(input).toLowerCase()
  if (!text) return null

  const hex = HEX_RE.exec(text)
  if (hex) return fromHexDigits(hex[1]!)

  const rgb = RGB_RE.exec(text)
  if (rgb) {
    return {
      r: byte(Number(rgb[1])),
      g: byte(Number(rgb[2])),
      b: byte(Number(rgb[3])),
      a: parseAlpha(rgb[4]),
    }
  }

  const hsl = HSL_RE.exec(text)
  if (hsl) {
    return {
      ...hslToRgb(Number(hsl[1]), Number(hsl[2]) / 100, Number(hsl[3]) / 100),
      a: parseAlpha(hsl[4]),
    }
  }

  return null
}

function parseAlpha(raw: string | undefined): number {
  if (raw === undefined) return 1
  const n = raw.endsWith("%") ? Number(raw.slice(0, -1)) / 100 : Number(raw)
  return Number.isFinite(n) ? clamp(n, 0, 1) : 1
}

function fromHexDigits(digits: string): RGB | null {
  // 3 and 4 digit shorthands expand by doubling each nibble.
  const expand = (s: string) => s.split("").map((c) => c + c).join("")
  let hex = digits
  if (hex.length === 3 || hex.length === 4) hex = expand(hex)
  if (hex.length !== 6 && hex.length !== 8) return null

  const int = Number.parseInt(hex, 16)
  if (!Number.isFinite(int)) return null

  if (hex.length === 6) {
    return { r: (int >> 16) & 255, g: (int >> 8) & 255, b: int & 255, a: 1 }
  }
  return {
    r: (int >>> 24) & 255,
    g: (int >>> 16) & 255,
    b: (int >>> 8) & 255,
    a: (int & 255) / 255,
  }
}

function hslToRgb(h: number, s: number, l: number): Omit<RGB, "a"> {
  const hue = ((h % 360) + 360) % 360
  const c = (1 - Math.abs(2 * l - 1)) * s
  const x = c * (1 - Math.abs(((hue / 60) % 2) - 1))
  const m = l - c / 2
  const [r, g, b] =
    hue < 60 ? [c, x, 0]
    : hue < 120 ? [x, c, 0]
    : hue < 180 ? [0, c, x]
    : hue < 240 ? [0, x, c]
    : hue < 300 ? [x, 0, c]
    : [c, 0, x]
  return { r: byte((r + m) * 255), g: byte((g + m) * 255), b: byte((b + m) * 255) }
}

/* ------------------------------------------------------------------ *
 * Output
 * ------------------------------------------------------------------ */

const hex2 = (n: number) => byte(n).toString(16).padStart(2, "0").toUpperCase()

/** Canonical hex. Uppercase, with alpha only when it is not fully opaque. */
export function toHex({ r, g, b, a }: RGB): string {
  const base = `#${hex2(r)}${hex2(g)}${hex2(b)}`
  return a >= 1 ? base : base + hex2(a * 255)
}

export function toRgbString({ r, g, b, a }: RGB): string {
  return a >= 1 ? `rgb(${r}, ${g}, ${b})` : `rgba(${r}, ${g}, ${b}, ${round2(a)})`
}

export function toHslString(rgb: RGB): string {
  const { h, s, l } = rgbToHsl(rgb)
  return rgb.a >= 1
    ? `hsl(${Math.round(h)}, ${Math.round(s * 100)}%, ${Math.round(l * 100)}%)`
    : `hsla(${Math.round(h)}, ${Math.round(s * 100)}%, ${Math.round(l * 100)}%, ${round2(rgb.a)})`
}

export function format(rgb: RGB, as: ColorFormat): string {
  return as === "rgb" ? toRgbString(rgb) : as === "hsl" ? toHslString(rgb) : toHex(rgb)
}

const round2 = (n: number) => Math.round(n * 100) / 100

export function rgbToHsl({ r, g, b }: RGB): { h: number; s: number; l: number } {
  const rn = r / 255
  const gn = g / 255
  const bn = b / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  const l = (max + min) / 2
  const d = max - min
  if (d === 0) return { h: 0, s: 0, l }

  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min)
  const h =
    max === rn ? ((gn - bn) / d + (gn < bn ? 6 : 0))
    : max === gn ? (bn - rn) / d + 2
    : (rn - gn) / d + 4
  return { h: h * 60, s, l }
}

/* ------------------------------------------------------------------ *
 * Contrast — WCAG 2.x relative luminance
 * ------------------------------------------------------------------ */

function channelLuminance(c: number): number {
  const v = c / 255
  return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4
}

/** WCAG relative luminance, 0 (black) to 1 (white). */
export function luminance({ r, g, b }: RGB): number {
  return (
    0.2126 * channelLuminance(r) +
    0.7152 * channelLuminance(g) +
    0.0722 * channelLuminance(b)
  )
}

/** WCAG contrast ratio between two colours. 1:1 to 21:1. */
export function contrastRatio(a: RGB, b: RGB): number {
  const la = luminance(a)
  const lb = luminance(b)
  const lighter = Math.max(la, lb)
  const darker = Math.min(la, lb)
  return (lighter + 0.05) / (darker + 0.05)
}

/** Whichever of black or white reads better on this colour. */
export function bestForeground(bg: RGB): "#000000" | "#FFFFFF" {
  const white = contrastRatio(bg, { r: 255, g: 255, b: 255, a: 1 })
  const black = contrastRatio(bg, { r: 0, g: 0, b: 0, a: 1 })
  return white >= black ? "#FFFFFF" : "#000000"
}

export type WcagLevel = "AA" | "AAA" | "AA-large" | "fail"

/** Which WCAG threshold this ratio clears. */
export function wcagLevel(ratio: number): WcagLevel {
  if (ratio >= 7) return "AAA"
  if (ratio >= 4.5) return "AA"
  if (ratio >= 3) return "AA-large"
  return "fail"
}

/* ------------------------------------------------------------------ *
 * Paste
 * ------------------------------------------------------------------ */

/**
 * Extract a colour from pasted text — a bare hex, a devtools `rgb(...)`, or a
 * CSS declaration like `color: #3A3FD6;`.
 */
export function parsePastedColor(input: string): RGB | null {
  const text = scrub(input)
  if (!text) return null

  const direct = parseColor(text)
  if (direct) return direct

  // Pull the first colour-ish token out of a longer string.
  const token =
    /#[a-f\d]{3,8}\b/i.exec(text)?.[0] ??
    /rgba?\([^)]*\)/i.exec(text)?.[0] ??
    /hsla?\([^)]*\)/i.exec(text)?.[0]

  return token ? parseColor(token) : null
}

/** A small, deliberately neutral default palette. */
export const DEFAULT_SWATCHES: readonly string[] = [
  "#0F172A",
  "#DC2626",
  "#EA580C",
  "#CA8A04",
  "#16A34A",
  "#0891B2",
  "#2563EB",
  "#7C3AED",
  "#DB2777",
]
